insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','restaurants','Before sending a guest to a restaurant late in the evening, what should you do?','Antes de enviar a un huésped a un restaurante tarde en la noche, ¿qué debes hacer?','["Check its posted hours and suggest calling ahead, because hours can change", "Tell them every restaurant nearby is open until midnight", "Promise it is open because our list says so", "Send them without checking so they are not delayed"]'::jsonb,'["Revisar su horario publicado y sugerir llamar antes, porque los horarios pueden cambiar", "Decirle que todos los restaurantes cercanos abren hasta medianoche", "Prometer que está abierto porque nuestra lista lo dice", "Enviarlo sin revisar para no retrasarlo"]'::jsonb,0,'Holiday, event and staffing changes can shift hours. Our restaurant list shows the date its hours were last checked, so confirm with a quick call.','Los días festivos, eventos y el personal pueden cambiar los horarios. Nuestra lista muestra la fecha de la última revisión, así que confirma con una llamada rápida.','https://www.gooddaycafe.com/',array['front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
