insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A guest asks for sushi or Japanese food nearby. Which of these fits?','Un huésped pide sushi o comida japonesa cerca. ¿Cuál de estos encaja?','["Benihana", "Sweetgreen", "Pizza Novara", "D. Brian''s Kitchen & Catering"]'::jsonb,'["Benihana", "Sweetgreen", "Pizza Novara", "D. Brian''s Kitchen & Catering"]'::jsonb,0,'Benihana is listed as Japanese/sushi; the others serve different food.','Benihana aparece como japonesa/sushi; los demás sirven otra comida.','https://www.mallofamerica.com/directory/benihana',array['front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
