insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A family wants a coffee shop tonight. Which of these serves it?','Una familia quiere una cafetería esta noche. ¿Cuál de estos lo sirve?','["Starbucks", "Piada Italian Street Food", "Sweetgreen", "Culver''s"]'::jsonb,'["Starbucks", "Piada Italian Street Food", "Sweetgreen", "Culver''s"]'::jsonb,0,'Starbucks is listed as a coffee shop; the others serve different food.','Starbucks aparece como café; los demás sirven otra comida.','https://www.mallofamerica.com/directory/starbucks-coffee-west2',array['driver','front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspms','driver']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A guest does not have a car and asks what they can walk to. Which of these is within about a 15-minute walk (roughly 0.8 miles or less) of our hotel?','Un huésped sin auto pregunta a dónde puede ir caminando. ¿Cuál de estos está a unos 15 minutos a pie (aprox. 0.8 millas o menos) de nuestro hotel?','["Davanni''s Pizza & Hot Hoagies", "Pizza Novara", "Culver''s", "Sports Page Bar & Grill"]'::jsonb,'["Davanni''s Pizza & Hot Hoagies", "Pizza Novara", "Culver''s", "Sports Page Bar & Grill"]'::jsonb,1,'Pizza Novara is about 0.7 miles away by road, roughly a 15-minute walk (estimate). The others are 2+ miles away by car.','Pizza Novara está a unas 0.7 millas por carretera, más o menos 15 minutos a pie (estimado). Los demás están a más de 2 millas en auto.','https://pizzanovara.com/',array['driver','front_desk','night_audit']::text[],'role','med',array['hotel','restaurants','mspms','driver']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A family wants to eat without leaving Mall of America. Which of these is inside the mall?','Una familia quiere comer sin salir del Mall of America. ¿Cuál de estos está dentro del centro comercial?','["Chevys Fresh Mex", "Pizza Novara", "Twin City Grill", "Hong Kong Noodle"]'::jsonb,'["Chevys Fresh Mex", "Pizza Novara", "Twin City Grill", "Hong Kong Noodle"]'::jsonb,2,'Twin City Grill is a Mall of America tenant. The others are outside the mall.','Twin City Grill está dentro del Mall of America. Los demás están fuera del centro comercial.','https://www.mallofamerica.com/directory/twin-city-grill',array['driver','front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspms','driver']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A guest is shopping at MOA and asks for lunch inside the mall. Which of these is inside MOA?','Un huésped compra en MOA y pide almuerzo dentro del centro. ¿Cuál de estos está dentro de MOA?','["D. Brian''s Kitchen & Catering", "Chevys Fresh Mex", "Culver''s", "CRAVE"]'::jsonb,'["D. Brian''s Kitchen & Catering", "Chevys Fresh Mex", "Culver''s", "CRAVE"]'::jsonb,3,'CRAVE is a Mall of America tenant. The others are outside the mall.','CRAVE está dentro del Mall of America. Los demás están fuera del centro comercial.','https://www.mallofamerica.com/directory/crave',array['front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A guest wants dinner out on a Sunday. Which of these is closed on Sundays?','Un huésped quiere cenar fuera un domingo. ¿Cuál de estos cierra los domingos?','["Bubba Gump Shrimp Co.", "Starbucks", "D. Brian''s Kitchen & Catering", "Great Steak & Potato"]'::jsonb,'["Bubba Gump Shrimp Co.", "Starbucks", "D. Brian''s Kitchen & Catering", "Great Steak & Potato"]'::jsonb,2,'D. Brian''s Kitchen & Catering is closed on Sundays per its listing. The others post Sunday hours. Always call to confirm.','D. Brian''s Kitchen & Catering cierra los domingos según su ficha. Los demás publican horario de domingo. Siempre confirma por teléfono.','https://dbrians.com/ordering-menus/',array['front_desk','night_audit']::text[],'role','med',array['hotel','restaurants','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','A guest asks you to call Panda Express to check the wait. Which number is theirs?','Un huésped te pide llamar a Panda Express para ver la espera. ¿Cuál es su número?','["(952) 222-4000", "(952) 854-5538", "(952) 854-5112", "(952) 858-8115"]'::jsonb,'["(952) 222-4000", "(952) 854-5538", "(952) 854-5112", "(952) 858-8115"]'::jsonb,3,'Panda Express: (952) 858-8115 (from its listing). Re-check if a call does not connect.','Panda Express: (952) 858-8115 (de su ficha). Verifica de nuevo si no contesta.','https://www.mallofamerica.com/directory/panda-express-south',array['front_desk','night_audit']::text[],'role','med',array['hotel','restaurants','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','restaurants','Before sending a guest to a restaurant late in the evening, what should you do?','Antes de enviar a un huésped a un restaurante tarde en la noche, ¿qué debes hacer?','["Promise it is open because our list says so", "Send them without checking so they are not delayed", "Check its posted hours and suggest calling ahead, because hours can change", "Tell them every restaurant nearby is open until midnight"]'::jsonb,'["Prometer que está abierto porque nuestra lista lo dice", "Enviarlo sin revisar para no retrasarlo", "Revisar su horario publicado y sugerir llamar antes, porque los horarios pueden cambiar", "Decirle que todos los restaurantes cercanos abren hasta medianoche"]'::jsonb,2,'Holiday, event and staffing changes can shift hours. Our restaurant list shows the date its hours were last checked, so confirm with a quick call.','Los días festivos, eventos y el personal pueden cambiar los horarios. Nuestra lista muestra la fecha de la última revisión, así que confirma con una llamada rápida.','https://www.mallofamerica.com/directory/rainforest-cafe',array['front_desk','night_audit']::text[],'role','easy',array['hotel','restaurants','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
